FoamFile
{
    version     2.0;
    format      ascii;
    class       dictionary;
    note        "mesh renumbering dictionary";
    object      renumberMeshDict;
}
// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //

// Additional libraries
//libs        (SloanRenumber);
//libs        (zoltanRenumber);

// Optional entry: write maps from renumbered back to original mesh
writeMaps   false;

// Optional entry: sort cells on coupled boundaries to last for use with
// e.g. nonBlockingGaussSeidel.
sortCoupledFaceCells false;

// Optional entry: renumber on a block-by-block basis. It uses a
// blockCoeffs dictionary to construct a decompositionMethod to do
// a block subdivision) and then applies the renumberMethod to each
// block in turn. This can be used in large cases to keep the blocks
// fitting in cache with all the cache misses bunched at the end.
// This number is the approximate size of the blocks - this gets converted
// to a number of blocks that is the input to the decomposition method.
//blockSize 1000;

// Optional entry: sort points into internal and boundary points
//orderPoints false;

// Optional entry (experimental) - for block-by-block (blockSize > 0) option:
// - sort intra-region and iter-region faces separately.
//   This will likely lead to non-upper triangular ordering between regions.
//regionFaceOrder false;


method          CuthillMcKee;
//method          RCM;  // == reverseCuthillMcKee;
//method          Sloan;        //<-  libs (zoltanRenumber);
//method          manual;
//method          random;
//method          structured;
//method          spring;
//method          zoltan;       //<-  libs (zoltanRenumber);

//CuthillMcKeeCoeffs
//{
//    // Plain or reverse CuthillMcKee (RCM)
//    reverse     true;
//}

manualCoeffs
{
    // In system directory: new-to-original (i.e. order) labelIOList
    dataFile    "cellMap";
}


// For extruded (i.e. structured in one direction) meshes
structuredCoeffs
{
    // Patches that mesh was extruded from.
    // These determine the starting layer of cells
    patches     (movingWall);

    // Method to renumber the starting layer of cells
    method      random;

    // Renumber in columns (depthFirst) or in layers
    depthFirst  true;

    // Reverse ordering
    reverse     false;
}


springCoeffs
{
    // Maximum jump of cell indices. Is fraction of number of cells
    maxCo       0.01;

    // Limit the amount of movement; the fraction maxCo gets decreased
    // with every iteration
    freezeFraction 0.999;

    // Maximum number of iterations
    maxIter    1000;

    // Enable/disable verbosity
    verbose    true;
}


blockCoeffs
{
    method      scotch;
    //method      hierarchical;
    //hierarchicalCoeffs
    //{
    //    n           (1 2 1);
    //    delta       0.001;
    //    order       xyz;
    //}
}


zoltanCoeffs
{
    ORDER_METHOD    LOCAL_HSFC;
}


// ************************************************************************* // 相关命令 renumberMesh 常见问题 现象 检查方法 边界名称与字段不一致 修改拓扑后，更新 constant/polyMesh/boundary 和所有 0/ 场文件中的边界配置。 单位或坐标方向错误 比较几何包围盒与预期物理尺寸；检查 scale、挤出法向和旋转轴。 网格生成成功但质量不足 运行 checkMesh -allTopology -allGeometry，再评估所选离散格式对非正交和扭曲的容忍度。 配置来源： OpenFOAM v2512 教程 · GPL-3.0-or-later 。

配置运动黏度、输运模型或两相物性；具体结构由求解器读取的模型决定。 简要介绍 这个文件向相应求解器提供黏度、扩散系数或输运模型，决定动量和标量如何扩散。简单不可压缩流常在这里给出运动黏度，多相或非牛顿问题则需要按所选模型组织各自的物性条目。 位置： constant/transportProperties 配置方法 constant/transportProperties 常用于不可压缩求解器中的黏度或标量扩散系数。字段名称和模型结构取决于求解器读取的物性类。 配置示例 示例 1 · 牛顿流体 采用 singlePhaseTransportModel 的不可压缩求解器，例如 simpleFoam ，可在标准文件头之后使用： transportModel Newtonian;
nu [0 2 -1 0 0 0 0] 1e-6; Newtonian 指定牛顿黏性模型， nu 是运动黏度，单位为 \(\mathrm{m^2/s}\)。七个量纲指数依次表示质量、长度、时间、温度、物质的量、电流和发光强度。 动力黏度 \(\mu\) 与运动黏度的关系为 \(\nu=\mu/\rho\)。例如 \(\mu=0.001\,\mathrm{Pa\,s}\)、\(\rho=1000\,\mathrm{kg/m^3}\) 时，\(\nu=10^{-6}\,\mathrm{m^2/s}\)。将动力黏度的数值直接填进 nu 会使黏性尺度改变三个数量级。 基础 icoFoam 直接读取 nu ，其方腔文件只需对应黏度条目。对固定速度和长度，黏度越小，雷诺数 \(Re=UL/\nu\) 越大，网格与时间分辨率需求也可能提高。 示例 2 · 标量扩散 laplacianFoam 和 scalarTransportFoam 使用 DT ，其主体配置可写为： DT [0 2 -1 0 0 0 0] 1e-5; 若 T 表示温度， DT 是热扩散率 \(k/(\rho c_p)\)；如果是一般被动标量，它是相应的扩散系数。在 scalarTransportFoam 中设 DT=0 可研究纯对流；在 laplacianFoam 中增大 DT 会加快温度扩散。 对于两端固定温度的均匀一维杆，稳态温度直线与常数 DT 的大小无关；达到稳态的时间尺度约为 \(L^2/DT\)。因此，改变 DT 后要分别看稳态分布与瞬态演化。 示例 3 · 扩展到非牛顿流体 非牛顿模型使有效运动黏度随剪切率等量变化。修改时需要同时指定 transportModel 和所选模型的系数子字典，并检查系数的单位及上下限。可从 v2512 中使用相同模型的完整教程出发，避免将牛顿流体的单一 nu 当作全部输入。 查看当前值可运行： foamDictionary constant/transportProperties -entry nu -value 对于标量例子，将 nu 换成 DT 。修改物性后同时记录雷诺数或扩散时间尺度，能更直接理解流场为何变化。 配套案例文件 下载配置后，可从案例目录取得配套网格、初始场和 include 文件。 案例文件 1 · incompressible/icoFoam/cavity/cavity 算例问题：cavity 封闭方腔的顶盖沿切向运动，其他壁面保持静止，顶盖通过黏性作用带动腔内流体。计算产生主涡和角部回流，用于检查速度、压力以及网格分辨率对流动结构的影响。 算例出处：OpenCFD OpenFOAM v2512 官方教程 incompressible/icoFoam/cavity/cavity 。 cavity 的物理问题示意；用于说明计算对象与主要物理过程，不代表计算结果。 方腔只有一个牛顿流体， icoFoam 直接从这里读取运动黏度。 nu 0.01 的单位为 \(\mathrm{m^2/s}\)，用于动量方程中的黏性扩散。 配套顶盖速度为 1 m/s、腔长为 0.1 m，因此 \(Re=UL/\nu=10\)，黏性作用明显，适合观察层流回流结构。 这个短字典采用求解器已知的参数量纲；运动黏度与动力黏度的关系为 \(\mu=\rho\nu\)。 想考察较高 Reynolds 数，可减小 nu ，同时检查网格和时间步是否能够解析更薄的剪切层。例如改成 0.001 ，其余条件不变时 \(Re=100\)。 下载配置 · 源码 · 案例目录 配置出处：OpenCFD OpenFOAM v2512 官方教程 incompressible/icoFoam/cavity/cavity/constant/transportProperties （原文件）。 /*--------------------------------*- C++ -*----------------------------------*\
