fieldAverage
{
    type            fieldAverage;
    libs            (fieldFunctionObjects);

    enabled         true;
    writeControl    writeTime;

    timeStart       $tStartAvg;

    fields
    (
        U
        {
            mean            on;
            prime2Mean      on;
            base            time;
        }
        p
        {
            mean            on;
            prime2Mean      off;
            base            time;
        }
        nut
        {
            mean            on;
            prime2Mean      off;
            base            time;
        }
        nuTilda
        {
            mean            on;
            prime2Mean      off;
            base            time;
        }
        wallShearStress
        {
            mean            on;
            prime2Mean      off;
            base            time;
        }
    );
}

