FoamFile
{
    version     2.0;
    format      ascii;
    class       dictionary;
    object      controlDict;
}
// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //

application     simpleFoam;

startFrom       startTime;

startTime       0;

stopAt          endTime;

endTime         5000;

deltaT          1;

writeControl    timeStep;

writeInterval   100;

purgeWrite      1;

writeFormat     ascii;

writePrecision  8;

writeCompression off;

timeFormat      general;

timePrecision   8;

runTimeModifiable true;

functions
{
    minMax
    {
        type          fieldMinMax;
        libs          (fieldFunctionObjects);
        writeControl  timeStep;
        fields        (U);
    }

    yPlus
    {
        type            yPlus;
        libs            (fieldFunctionObjects);
        patches         (fixedWall);
        writeFields     yes;
        writeControl    writeTime;
    }

    #includeFunc "writeCellCentres"
    #includeFunc "wallShearStress"
}


// ************************************************************************* // 案例文件 2 · incompressible/simpleFoam/bump2D/setups.orig/common 算例问题：incompressible/simpleFoam/bump2D/setups.orig/common 来流越过壁面上的凸起，压力梯度引起边界层增厚、分离或再附着。算例用于研究湍流闭合和近壁处理对回流区、壁面压力及摩擦的影响。 算例出处：OpenCFD OpenFOAM v2512 官方教程 incompressible/simpleFoam/bump2D/setups.orig/common 。 bump2D 用 y⁺、壁面剪应力、压力系数与总载荷共同检查凸起壁面附近流动。 yPlus 开启 writeFields yes 并在 writeTime 保存。 wallShearStress 对 bump patch 输出壁面剪切。 pressure 函数对象以 UInf (69.44 0 0) 、 rhoInf 1 等参考量计算 Cp。 主场每 100 次迭代写出，最多保留最近 3 份结果。 改变近壁网格后同时比较 y⁺、Cp 和分离位置，保留同一参考速度与几何尺度。 下载配置 · 源码 · 案例目录 配置出处：OpenCFD OpenFOAM v2512 官方教程 incompressible/simpleFoam/bump2D/setups.orig/common/system/controlDict （原文件）。 /*--------------------------------*- C++ -*----------------------------------*\
| =========                 |                                                 |
| \\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |
|  \\    /   O peration     | Version:  v2512                                 |
|   \\  /    A nd           | Website:  www.openfoam.com                      |
|    \\/     M anipulation  |                                                 |
\*---------------------------------------------------------------------------*/
FoamFile
{
    version     2.0;
    format      ascii;
    class       dictionary;
    object      controlDict;
}
// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //

application     simpleFoam;

startFrom       startTime;

startTime       0;

stopAt          endTime;

endTime         10000;

deltaT          1;

writeControl    timeStep;

writeInterval   100;

purgeWrite      3;

writeFormat     ascii;

writePrecision  8;

writeCompression off;

timeFormat      general;

timePrecision   8;

runTimeModifiable true;

functions
{
    pressure
    {
        type            pressure;
        libs            (fieldFunctionObjects);
        writeControl    writeTime;
        result          Cp;
        mode            staticCoeff;
        rho             rhoInf;
        rhoInf          1;
        U               UInf;
        UInf            (69.44 0 0);
        pInf            0;
    }

    forceCoeffs
    {
        type            forceCoeffs;
        libs            (forces);
        writeControl    writeTime;
        rho             rhoInf;
        rhoInf          1;
        liftDir         (0 1 0);
        dragDir         (1 0 0);
        CofR            (0.75 0 0); // bump midpoint
        pitchAxis       (0 0 1);
        magUInf         69.44;
        lRef            0.9; // length of bump
        Aref            0.1; // mesh span = 2, bump height = 0.05; 2*0.05=0.1
        patches         (bump);
    }

    wallShearStress
    {
        type            wallShearStress;
        libs            (fieldFunctionObjects);
        writeFields     yes;
        writeControl    writeTime;
        patches         (bump);
    }

    yPlus
    {
        type            yPlus;
        libs            (fieldFunctionObjects);
        writeFields     yes;
        writeControl    writeTime;
    }

    cellCentres
    {
        type            writeCellCentres;
        libs            (fieldFunctionObjects);
        writeControl    writeTime;
    }

    residuals
    {
        type            solverInfo;
        libs            (utilityFunctionObjects);
        fields          (".*");
    }
}


// ************************************************************************* // 案例文件 3 · incompressible/pimpleFoam/LES/surfaceMountedCube/fullCase 算例问题：fullCase 壁面上安装方块，来流边界层遇到方块后分离，并在侧面和下游形成复杂回流。主算例关注方块周围流动，initChannel 子算例用于准备与主计算相配合的入口通道流。 算例出处：OpenCFD OpenFOAM v2512 官方教程 incompressible/pimpleFoam/LES/surfaceMountedCube/fullCase 。 绕立方体的 LES 完整算例把近壁分辨率、涡结构和时间统计一并输出。 yPlus 使用 fieldFunctionObjects ， writeFields yes 保存场。 writeControl writeTime 跟随主场，每 100 步写出；固定 deltaT 0.002 时对应 0.2 s。 fieldAverage 从 timeStart 10 开始，对 U、p 计算均值和二阶脉动量。 Q、vorticity 与 DESField 提供流动结构和模型区域信息。 比较壁面模型或网格时固定统计时段，再看 y⁺、平均流动与波动强度是否共同变化。 下载配置 · 源码 · 案例目录 配置出处：OpenCFD OpenFOAM v2512 官方教程 incompressible/pimpleFoam/LES/surfaceMountedCube/fullCase/system/controlDict （原文件）。 /*--------------------------------*- C++ -*----------------------------------*\
| =========                 |                                                 |
| \\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |
|  \\    /   O peration     | Version:  v2512                                 |
|   \\  /    A nd           | Website:  www.openfoam.com                      |
