|   \\  /    A nd           | Website:  www.openfoam.com                      |
|    \\/     M anipulation  |                                                 |
\*---------------------------------------------------------------------------*/
FoamFile
{
    version     2.0;
    format      ascii;
    class       dictionary;
    object      PDRblockMeshDict;
}
// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //

scale   0.1;

x
{
    points  (0 1);
    nCells  (20);
    ratios  (1);
}

y
{
    points  (0 1);
    nCells  (20);
    ratios  (1);
}

z
{
    points  (0 0.1);
    nCells  (1);
    ratios  (1);
}


boundary
(
    movingWall
    {
        type  wall;
        faces (3);
    }
    fixedWalls
    {
        type  wall;
        faces (0 1 2);
    }
    frontAndBack
    {
        type  empty;
        faces (4 5);
    }
);


// ************************************************************************* // 案例文件 2 · incompressible/lumpedPointMotion/bridge/steady 算例问题：steady 桥梁结构的运动以若干集中点及连接关系描述，并与周围流体载荷联系。该子目录用于准备稳态流场，后续结构运动需要结合集中点运动参数和流体力信息。 算例出处：OpenCFD OpenFOAM v2512 官方教程 incompressible/lumpedPointMotion/bridge/steady 。 桥梁算例用分段网格覆盖桥梁附近与较远的外流区域，随后配合桥体几何及运动处理。 x 从 −50 到 50，分 50 格，对应均匀间距 2 m。 y 分成 −300～−25、−25～25、25～300 三段，每段 10 格；中间段间距 5 m，两侧间距 27.5 m，桥梁附近分辨率更高。 z 的 0～50、50～80、80～250 分别用 2、10、10 格，形成地面到高空的不同网格尺度。 面 2 是 outlet，3 是 inlet，4 是 ground 壁面，5 是 sky，其余为 sides；这些名称会被后续场文件引用。 本文件 ratios 1 使每一段内部均匀。需要平滑过渡时，同时调整分段位置、单元数和扩张比，并检查相邻单元尺寸跳变。 下载配置 · 源码 · 案例目录 配置出处：OpenCFD OpenFOAM v2512 官方教程 incompressible/lumpedPointMotion/bridge/steady/system/PDRblockMeshDict （原文件）。 /*--------------------------------*- C++ -*----------------------------------*\
| =========                 |                                                 |
| \\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |
|  \\    /   O peration     | Version:  v2512                                 |
|   \\  /    A nd           | Website:  www.openfoam.com                      |
|    \\/     M anipulation  |                                                 |
\*---------------------------------------------------------------------------*/
FoamFile
{
    version     2.0;
    format      ascii;
    class       dictionary;
    object      PDRblockMeshDict;
}
// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //

// Bounding Box : (-23.275 -250 5) (23.275 250 200)

scale   1;

x
{
    points  ( -50 50 );
    nCells  ( 50 );
    ratios  ( 1 );
}

y
{
    points  ( -300 -25 25 300 );
    nCells  ( 10 10 10 );
    ratios  ( 1 1 1 );
}

z
{
    points  ( 0 50 80 250 );
    nCells  ( 2 10 10 );
    ratios  ( 1 1 1 );
}

// Low resolution


// Faces: 0=x-min, 1=x-max, 2=y-min, 3=y-max, 4=z-min, 5=z-max

boundary
(
    sides
    {
        type    patch;
        faces   ( 0 1 );
    }

    outlet
    {
        type    patch;
        faces   ( 2 );
    }

    inlet
    {
        type    patch;
        faces   ( 3 );
    }

    ground
    {
        type    wall;
        faces   ( 4 );
    }

    sky
    {
        type    patch;
        faces   ( 5 );
    }
);

// ************************************************************************* // 案例文件 3 · combustion/PDRFoam/pipeLattice 算例问题：pipeLattice 预混可燃气体中的火焰传播受到管架或障碍物影响，障碍物会改变阻力、湍流和燃烧传播速度。PDR 方法用网格上的等效堵塞与阻力描述未逐一解析的结构；预处理算例负责生成这些场，燃烧算例再求解压力和火焰演化。 算例出处：OpenCFD OpenFOAM v2512 官方教程 combustion/PDRFoam/pipeLattice 。 pipeLattice 在管阵列附近布置较细网格，向外部开阔区域扩展。PDRblockMeshDict 决定这层背景网格。 x 的三段为 −19.4～0、0～4.26、4.26～23.66，分别用 14、13、14 格；y 采用对应的三段划分。 中间区域扩张比为 1，外侧比值约 0.0887 和 10.699，使网格向障碍物附近收缩、向远处增大。 z 从地面起分为 0～2.13 的 6 格、2.13～23.17 的 14 格，远离地面后逐渐放粗。 outer 包含四个侧面与顶面， wallFaces 对应底面 4；blockedFaces、mergingFaces 预留给后续障碍物处理。 调整阵列尺寸后同步修改分段位置和障碍物几何，检查细网格是否覆盖全部管阵列。 下载配置 · 源码 · 案例目录 配置出处：OpenCFD OpenFOAM v2512 官方教程 combustion/PDRFoam/pipeLattice/system/PDRblockMeshDict （原文件）。 /*--------------------------------*- C++ -*----------------------------------*\
| =========                 |                                                 |
| \\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |
|  \\    /   O peration     | Version:  v2512                                 |
|   \\  /    A nd           | Website:  www.openfoam.com                      |
|    \\/     M anipulation  |                                                 |
\*---------------------------------------------------------------------------*/
FoamFile
{
    version     2.0;
    format      ascii;
    class       dictionary;
    object      PDRblockMeshDict;
}
// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //

scale   1.0;

x
{
    points  ( -19.4 0 4.26 23.66 );
    nCells  ( 14 13 14 );
    ratios  ( 0.0887187064230887 1 10.6993205379072 );
}

y
{
    points  ( -19.42 0 4.26 23.68 );
    nCells  ( 14 13 14 );
    ratios  ( 0.0887187064230887 1 10.6993205379072 );
}

z
{
    points  (0 2.13 23.17  );
    nCells  ( 6 14 );
    ratios  ( 1 10.6993205379072 );
}


// Or could use defaultFaces = outer instead
defaultPatch
{
    name    defaultFaces;
    type    wall;
}


// Faces: 0 = xmin, 1 = xmax, 2 = ymin, 3 = ymax, 4 = zmin, 5 = zmax

boundary
(
    // Or with defaultFaces = outer
    outer
    {
        type    patch;
        faces   ( 0 1 2 3 5 );
    }

    mergingFaces
    {
        type    wall;
        faces   ();
    }

    blockedFaces
    {
        type    wall;
        faces   ();
    }

    wallFaces
    {
        type    wall;
        faces   ( 4 );
    }
);


