| \\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |
|  \\    /   O peration     | Version:  v2512                                 |
|   \\  /    A nd           | Website:  www.openfoam.com                      |
|    \\/     M anipulation  |                                                 |
\*---------------------------------------------------------------------------*/
FoamFile
{
    version     2.0;
    format      ascii;
    class       dictionary;
    object      caseProperties;
}
// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //

initialConditions
{
    p       uniform 100000;
    rho     uniform 8000;
    T       uniform 300;
}


boundaryConditions
{
    thermalWalls
    {
        category    wall;
        type        thermal;
        patches     (minX minZ maxZ);
        options
        {
            heatTransfer adiabatic;
        }
        values
        {
            $/initialConditions;
        }
    }
    thermalCoupledWalls
    {
        category    wall;
        type        thermal;
        patches     (".*_to_.*");
        options
        {
            heatTransfer thermalCoupled;
        }
        values
        {
            $/initialConditions;
        }
    }
}


// ************************************************************************* // 案例文件 2 · preProcessing/createZeroDirectory/cavity 算例问题：cavity 本例为后续流动或传热计算建立初始场文件。封闭方腔的顶盖沿切向运动，其他壁面保持静止，顶盖通过黏性作用带动腔内流体。计算产生主涡和角部回流，用于检查速度、压力以及网格分辨率对流动结构的影响。 此目录侧重根据算例属性生成 0/ 下的场和边界配置，完整求解还需使用相应的流动或传热算例。 算例出处：OpenCFD OpenFOAM v2512 官方教程 preProcessing/createZeroDirectory/cavity 。 cavity 的物理问题示意；用于说明计算对象与主要物理过程，不代表计算结果。 方腔的 caseProperties 将“运动顶壁、静止固壁”等物理角色转换为具体的 U、p 边界配置。 初始 U (0 0 0) 表示静止流体， p 0 给出压力初值。 topWall 对应 movingWall， motion moving 和 U (1 0 0) 让顶壁沿 x 方向以 1 m/s 运动。 walls 对应 fixedWalls， motion stationary 生成静止无滑移壁面条件。 两组壁面都采用 type noSlip ；运动壁面的无滑移速度等于壁面自身速度。模板中其他通用选项由生成器按所选模型处理。 改变顶盖速度时修改 topWall 的 U，再重新生成初始场；可用生成后的 0/U 检查方向与数值。 下载配置 · 源码 · 案例目录 配置出处：OpenCFD OpenFOAM v2512 官方教程 preProcessing/createZeroDirectory/cavity/system/caseProperties （原文件）。 /*--------------------------------*- C++ -*----------------------------------*\
