FoamFile
{
    version     2.0;
    format      ascii;
    class       dictionary;
    object      dsmcProperties;
}
// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //


// General Properties
// ~~~~~~~~~~~~~~~~~~

nEquivalentParticles            1.2e12;


// Wall Interaction Model
// ~~~~~~~~~~~~~~~~~~~~~~

WallInteractionModel            MaxwellianThermal;


// Binary Collision Model
// ~~~~~~~~~~~~~~~~~~~~~~

BinaryCollisionModel            VariableHardSphere;

VariableHardSphereCoeffs
{
    Tref        273;
}


// Inflow Boundary Model
// ~~~~~~~~~~~~~~~~~~~~~

InflowBoundaryModel             FreeStream;

FreeStreamCoeffs
{
    numberDensities
    {
        Ar      1.0e20;
    };
}


// Molecular species
// ~~~~~~~~~~~~~~~~~

typeIdList                      (Ar);

moleculeProperties
{
    Ar
    {
        mass                            66.3e-27;
        diameter                        4.17e-10;
        internalDegreesOfFreedom        0;
        omega                           0.81;
    }
}


// ************************************************************************* // 案例文件 2 · discreteMethods/dsmcFoam/freeSpacePeriodic 算例问题：freeSpacePeriodic 稀薄气体分子在周期空间内自由飞行并发生统计碰撞。分子穿过周期边界后重新进入另一侧，算例用于检查 DSMC 的粒子运动、碰撞及宏观量统计。 算例出处：OpenCFD OpenFOAM v2512 官方教程 discreteMethods/dsmcFoam/freeSpacePeriodic 。 freeSpacePeriodic 的物理问题示意；用于说明计算对象与主要物理过程，不代表计算结果。 freeSpacePeriodic 使用氮氧双原子混合气，在周期区域中观察碰撞与能量分配。 nEquivalentParticles 1e12 给出统计权重； typeIdList (N2 O2) 定义可出现的两种分子。 两种分子的 internalDegreesOfFreedom 均为 2，对应这里采用的转动内能自由度。质量分别为 46.5e-27 、 53.12e-27 kg。 LarsenBorgnakkeVariableHardSphere 在可变硬球碰撞基础上加入平动与内能再分配。 relaxationCollisionNumber 5.0 对应模型中 \(1/5\) 的内能再分配抽样概率。 Tref 273 、氮气 omega 0.74 和氧气 omega 0.77 决定各物种的碰撞温度依赖。 InflowBoundaryModel none 与周期体系配合； SpecularReflection 是遇到实体壁面时使用的镜面反射模型，周期面继续按周期拓扑处理。 可改变 relaxationCollisionNumber 比较内能向平衡状态靠近的速度。调整模拟粒子权重时，保持真实数密度和分子物性不变，以单独评估统计分辨率。 下载配置 · 源码 · 案例目录 配置出处：OpenCFD OpenFOAM v2512 官方教程 discreteMethods/dsmcFoam/freeSpacePeriodic/constant/dsmcProperties （原文件）。 /*--------------------------------*- C++ -*----------------------------------*\
