        U               cellPoint;
        muc             cell;
        p               cell;
    }

    integrationSchemes
    {
        U               Euler;
    }
}

constantProperties
{
    rho0            1000;
}

subModels
{
    particleForces
    {
//        sphereDrag;
//        gravity;
    }

    injectionModels
    {
        model1
        {
