FoamFile
{
    version     2.0;
    format      ascii;
    class       dictionary;
    object      porosityProperties;
}
// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //

porosityModel JensenEtAl2014;

porosityEnabled true;

JensenEtAl2014Coeffs
{
    alpha 500;
    beta 2;
    gamma_p 0.34;
    d50 0.0159;
    KC 128;
}


// ************************************************************************* // 案例文件 3 · incompressible/porousSimpleFoam/straightDuctImplicit 算例问题：straightDuctImplicit 流体在通道中穿过指定的多孔区域，区域内的附加阻力降低流速并造成压降。网格中的多孔区域选择、阻力主方向及 Darcy–Forchheimer 系数共同决定结果，可比较上游、下游压力和流量。 算例出处：OpenCFD OpenFOAM v2512 官方教程 incompressible/porousSimpleFoam/straightDuctImplicit 。 straightDuctImplicit 的物理问题示意；用于说明计算对象与主要物理过程，不代表计算结果。 straightDuctImplicit 用 Darcy–Forchheimer 模型表示管道中的各向异性多孔阻力。 cellZone porosity 将阻力限定在名为 porosity 的单元区。 d (5e7 -1000 -1000) 的 x 分量是 5×10⁷ m⁻²；负分量采用“最大正分量的倍数”写法，因此 y、z 对应 5×10¹⁰ m⁻²，强烈抑制横向运动。 f (0 0 0) 关闭二次速度阻力项，保留线性 Darcy 项。 局部坐标的 e1、e2 分别沿 x、y，决定这些阻力主方向在网格中的方向。 旋转多孔介质时修改局部坐标方向；拟合实验压降时同时检查长度、黏度、流速和阻力单位。 下载配置 · 源码 · 案例目录 配置出处：OpenCFD OpenFOAM v2512 官方教程 incompressible/porousSimpleFoam/straightDuctImplicit/constant/porosityProperties （原文件）。 /*--------------------------------*- C++ -*----------------------------------*\
| =========                 |                                                 |
| \\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |
|  \\    /   O peration     | Version:  v2512                                 |
|   \\  /    A nd           | Website:  www.openfoam.com                      |
|    \\/     M anipulation  |                                                 |
