FoamFile
{
    version         2.0;
    format          ascii;
    class           dictionary;
    location        system;
    object          sampleDict;
}
// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //

// Set output format : choice of
//      raw
//      gnuplot
//      xmgr
setFormat raw;

// Surface output format. Choice of
//      none        : suppress output
//      foam        : separate points, faces and values file
//      vtk         : VTK ascii format
//      raw         : x y z value format for use with e.g. gnuplot 'splot'.
//
// Note:
// other formats such as obj, stl, etc can also be written (by proxy)
// but without any values!
surfaceFormat vtk;

// interpolationScheme. choice of
//      cell          : use cell-centre value only; constant over cells (default)
//      cellPoint     : use cell-centre and vertex values
//      cellPointFace : use cell-centre, vertex and face values.
// 1] vertex values determined from neighbouring cell-centre values
// 2] face values determined using the current face interpolation scheme
//    for the field (linear, gamma, etc.)
interpolationScheme cellPoint;

// Fields to sample.
fields
(
    T
    CO
    CO2
    H2
    H2O
    N2
    O2
    OH
    CH4
);


// Set sampling definition: choice of
//      uniform             evenly distributed points on line
//      face                one point per face intersection
//      midPoint            one point per cell, inbetween two face intersections
//      midPointAndFace     combination of face and midPoint
//
//      curve               specified points, not necessary on line, uses
//                          tracking
//      cloud               specified points, uses findCell
//
// axis: how to write point coordinate. Choice of
// - x/y/z: x/y/z coordinate only
// - xyz: three columns
//  (probably does not make sense for anything but raw)
// - distance: distance from start of sampling line (if uses line) or
//             distance from first specified sampling point
//
// type specific:
//      uniform, face, midPoint, midPointAndFace : start and end coordinate
//      uniform: extra number of sampling points
//      curve, cloud: list of coordinates
sets
{
    Centerline
    {
        type        uniform;
        axis        distance;

        start       (0.00001 0. 0. );
        end         (0.00001 0. 0.500);
        nPoints     500;
    }

    Radial_075
    {
        type        uniform;
        axis        distance;

        start       (0 0 0.054);
        end         (0.020 0 0.054);
        nPoints     100;
    }
    Radial_15
    {
        type        uniform;
        axis        distance;

        start       (0 0 0.108);
        end         (0.024 0.108);
        nPoints     100;
    }
    Radial_30
    {
        type        uniform;
        axis        distance;

        start       (0 0 0.216);
        end         (0.042 0 0.216);
        nPoints     100;
    }
    Radial_45
    {
        type        uniform;
        axis        distance;

        start       (0 0 0.324);
        end         (0.056 0 0.324);
        nPoints     100;
    }
    Radial_60
    {
        type        uniform;
        axis        distance;

        start       (0 0 0.432);
        end         (0.070 0 0.432);
        nPoints     100;
    }
    Radial_75
    {
        type        uniform;
        axis        distance;

        start       (0 0 0.54);
        end         (0.080 0 0.54);
        nPoints     100;
    }
}


// Surface sampling definition: choice of
//      plane : values on plane defined by point, normal.
//      patch : values on patch.
//
// 1] patches are not triangulated by default
// 2] planes are always triangulated
// 3] iso-surfaces are always triangulated
surfaces {}


// *********************************************************************** // 相关命令 postProcess 常见问题 现象 检查方法 未找到指定场或函数对象： No field / No functionObject 确认场已写出、当前时刻正确且所需库已加载；派生量可能必须先生成。 结果坐标或单位错误 记录采样坐标、截面法向和物理单位，尤其注意压力定义与法向通量符号。 峰值随采样方式改变 比较插值方案与网格分辨率；点值、面平均和体平均不是同一个量。 配置来源： OpenFOAM v2512 教程 · GPL-3.0-or-later 。

通过表达式为边界场赋值。 简要介绍 这个字典把边界字段的赋值写成表达式，并指定操作的场与 patch。它适合准备随位置变化的入口或热边界，由 setExprBoundaryFields 将数学表达式落实为边界数据。 位置： system/setExprBoundaryFieldsDict 边界表达式与目标字段 参数 说明 expressions 表达式操作列表；每项在自己的子字典中指定目标字段和 expression。 field / expression 目标字段名称与表达式文本。表达式结果类型、尺寸及目标量纲必须匹配。 variables 表达式中的局部变量定义，例如 ("a=2;")；每个表达式使用各自的作用域。 readFields 预读已有场，使表达式可以访问它们。 constants 表达式可引用的常量或条目，按字典路径引用。 pattern / target pattern 选择边界，target 选择写入的目标，例如 value；应与边界类型允许的条目一致。 _value1 操作名称，可自定。 配置示例 配套案例文件 下载配置后，可从案例目录取得配套网格、初始场和 include 文件。 案例文件 1 · compressible/rhoPimpleFoam/RAS/TJunctionAverage 算例问题：TJunctionAverage 流体从左侧进入 T 形通道，再从上、下两个出口分流。出口压力或流动阻力影响两支路的流量分配；带 Fan 的版本还通过风机或挡板设置改变支路压差。 算例出处：OpenCFD OpenFOAM v2512 官方教程 compressible/rhoPimpleFoam/RAS/TJunctionAverage 。 TJunctionAverage 用表达式向温度字段的指定边界条目写入空间分段数值，演示 setExprBoundaryFields 的字典操作。 field T 选择温度场， patch outlet2 指定要处理的边界。 表达式 pos().x() < 1e-4 ? 60 : 120 按面中心 x 坐标分成两区，分别生成 60 和 120。 target something 会将结果写入该边界下名为 something 的条目。若目的是设置边界的实际 value，应改成 target value ，并选用使用 value 的边界条件。 移植为实际温度设置时，数值使用 K，阈值使用网格坐标的长度单位；先检查分区位置，再执行写入。 下载配置 · 源码 · 案例目录 配置出处：OpenCFD OpenFOAM v2512 官方教程 compressible/rhoPimpleFoam/RAS/TJunctionAverage/system/setExprBoundaryFieldsDict （原文件）。 /*--------------------------------*- C++ -*----------------------------------*\
