{
    version     2.0;
    format      ascii;
    class       dictionary;
    object      setExprBoundaryFieldsDict;
}
// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //

pattern
{
    field   T;

    expressions
    (
        {
            patch   outlet2;
            target  something;
            expression #{ (pos().x() < 1e-4 ? 60 : 120) #};
        }
    );
}


// ************************************************************************* // 案例文件 2 · incompressible/simpleFoam/turbineSiting 算例问题：turbineSiting 风流经地形及风机布置区域，地表粗糙度和入口大气边界层影响可利用风速。算例用于检查风场发展与风机相关区域的设置，重点观察高度方向的速度分布及局部尾流。 算例出处：OpenCFD OpenFOAM v2512 官方教程 incompressible/simpleFoam/turbineSiting 。 turbineSiting 从入口、出口、侧面和顶面的速度计算风功率密度，并写入 windPowerDensity 的边界值。 readFields (U) 提前载入速度场， updateBCs 子字典中的 field windPowerDensity 指定要更新的目标场。 rho=1.2 使用空气密度 1.2 kg/m³，表达式 0.5*rho*pow(mag(U),3) 给出单位面积动能通量，单位 W/m²。 target value 将结果写到实际边界值；后续边界条目复用同一表达式，减少重复配置。 风速翻倍时该表达式结果变为原来的八倍。采用其他空气密度时修改 rho，并确认 U 的单位为 m/s。 下载配置 · 源码 · 案例目录 配置出处：OpenCFD OpenFOAM v2512 官方教程 incompressible/simpleFoam/turbineSiting/system/setExprBoundaryFieldsDict （原文件）。 /*--------------------------------*- C++ -*----------------------------------*\
| =========                 |                                                 |
| \\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |
|  \\    /   O peration     | Version:  v2512                                 |
|   \\  /    A nd           | Website:  www.openfoam.com                      |
|    \\/     M anipulation  |                                                 |
\*---------------------------------------------------------------------------*/
FoamFile
{
    version     2.0;
    format      ascii;
    class       dictionary;
    object      setExprBoundaryFieldsDict;
}
// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //

// Preload any required fields (optional)
readFields      ( U );

updateBCs
{
    field   windPowerDensity;

    _value1
    {
        target      value;
        variables   ( "rho=1.2" );
        expression  #{ 0.5*rho*pow(mag(U),3) #};
    }

    expressions
    (
        { $_value1; patch inlet; }
        { $_value1; patch outlet; }
        { $_value1; patch sides; }
        { $_value1; patch top; }
    );
}


