// ************************************************************************* // 案例文件 2 · lagrangian/reactingParcelFoam/cylinder 算例问题：cylinder 水滴在重力和流体阻力作用下运动，与圆柱表面的液膜交换质量。本例启用表面液膜模型，而液滴换热、相变及化学反应模型设为 none；主要检查液滴轨迹、碰壁处理和液膜分布。 算例出处：OpenCFD OpenFOAM v2512 官方教程 lagrangian/reactingParcelFoam/cylinder 。 cylinder 使用单层热液膜模型描述液滴落到圆柱表面后的铺展和沿壁面流动。 thermoSingleLayer 、 active true 开启膜的质量、动量和热过程； region wallFilmRegion 指向独立的薄层网格区域。 filmThermoModel liquid 、 liquid H2O 、 useReferenceValues no 采用水的液体物性模型； filmViscosityModel liquid 同样从液体物性得到黏度。 deltaWet 1e-4 m 给出干湿判别的膜厚尺度， hydrophilic no 采用非强制亲水的润湿设置。 turbulence laminar 与 Cf 0.005 配置层流膜内的摩擦处理； thermocapillary 根据表面张力梯度产生切向作用。 上下表面的常数换热系数均为 c0 1e-8 ，对应近似隔热的设置；蒸发、辐射和膜主动注入模型在此关闭。 可改变 deltaWet 比较润湿面积的判定，再改变入射液滴流率观察膜厚。若研究壁面加热，应设置有物理依据的下表面换热系数与壁温，并观察膜温及表面张力梯度。 下载配置 · 源码 · 案例目录 配置出处：OpenCFD OpenFOAM v2512 官方教程 lagrangian/reactingParcelFoam/cylinder/constant/surfaceFilmProperties （原文件）。 /*--------------------------------*- C++ -*----------------------------------*\
| =========                 |                                                 |
| \\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |
|  \\    /   O peration     | Version:  v2512                                 |
|   \\  /    A nd           | Website:  www.openfoam.com                      |
|    \\/     M anipulation  |                                                 |
\*---------------------------------------------------------------------------*/
FoamFile
{
    version     2.0;
    format      ascii;
    class       dictionary;
    object      surfaceFilmProperties;
}
// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //

surfaceFilmModel thermoSingleLayer;

region          wallFilmRegion;

active          true;

thermoSingleLayerCoeffs
{
    filmThermoModel liquid;

    liquidCoeffs
    {
        useReferenceValues  no;
        liquid      H2O;
    }

    filmViscosityModel liquid;

    deltaWet    1e-4;

    hydrophilic no;

    turbulence  laminar;
    laminarCoeffs
    {
        Cf          0.005;
    }

    forces
    (
        thermocapillary
    );

    injectionModels ();

    phaseChangeModel none;

    radiationModel none;

    upperSurfaceModels
    {
        heatTransferModel constant;
        constantCoeffs
        {
            c0                1e-8;
        }
    }

    lowerSurfaceModels
    {
        heatTransferModel constant;
        constantCoeffs
        {
            c0                1e-8;
        }
    }
}


// ************************************************************************* // 案例文件 3 · lagrangian/reactingParcelFoam/splashPanel 算例问题：splashPanel 液滴撞击板面后与表面液膜发生交换，部分质量可能沉积或重新形成飞溅液滴。算例用于配套设置液滴碰壁和液膜模型，并检查沉积、飞溅与液膜质量之间的收支。 算例出处：OpenCFD OpenFOAM v2512 官方教程 lagrangian/reactingParcelFoam/splashPanel 。 splashPanel 将颗粒撞壁过程与平板液膜耦合，用膜区域记录液体的铺展和累积。 thermoSingleLayer 在 wallFilmRegion 上推进液膜，液体为 H2O ，黏度与热物性通过液体模型求取。 deltaWet 2e-4 m 对应 0.2 mm 的润湿判别尺度，比圆柱示例的阈值更大；其影响体现在薄膜区域的干湿识别。 hydrophilic no 、 turbulence laminar 和 Cf 0.005 分别控制润湿处理与膜内摩擦。 forces (thermocapillary) 包含热毛细作用；上下表面 c0 1e-8 使该例的换热接近关闭。 膜自身的 injectionModels 为空，膜蒸发和辐射均关闭。液滴撞击、吸收或飞溅的判据需要与颗粒云端的膜相互作用模型一起阅读。 提高注入速度可改变撞击动量，增加流量可提高膜内积液量。比较时分别记录入射颗粒、离开壁面的颗粒和液膜质量，并保持同一膜网格与干湿阈值。 下载配置 · 源码 · 案例目录 配置出处：OpenCFD OpenFOAM v2512 官方教程 lagrangian/reactingParcelFoam/splashPanel/constant/surfaceFilmProperties （原文件）。 /*--------------------------------*- C++ -*----------------------------------*\
